def check_key(dictionary, key):
    for k, v in dictionary.items():
        if k == key:
            return True
        if isinstance(v, dict):
            if check_key(v, key):
                return True
        elif isinstance(v, list):
            for item in v:
                if isinstance(item, dict) and check_key(item, key):
                    return True
    return False

