def convert_temperature(temp, conversion_type):
    # Ensure conversion_type is either 'c_to_f' or 'f_to_c'
    if conversion_type not in ['c_to_f', 'f_to_c']:
        raise ValueError("Invalid conversion type. Use 'c_to_f' or 'f_to_c'.")

    # Validate input is a valid number
    try:
        temp = float(temp)
    except ValueError:
        raise ValueError("Invalid temperature value. Please enter a number.")

    if conversion_type == 'c_to_f':
        # Convert Celsius to Fahrenheit
        result = (temp * 9 / 5) + 32
    else:
        # Convert Fahrenheit to Celsius
        result = (temp - 32) * 5 / 9

    return result

