def gcd(a: int, b: int) -> int:
    if a < 0 or b < 0:
        raise ValueError("Inputs must be non-negative.")
    if a == 0 and b == 0:
        raise ValueError("gcd(0, 0) is undefined.")
    while b != 0:
        a, b = b, a % b
    return a

