from typing import Dict, Any

def flatten_dict(nested_dict: Dict[str, Any]) -> Dict[str, Any]:
    """Flatten a nested dictionary into a single-level dictionary.

    Nested keys are joined with a dot ('.') separator.

    Args:
        nested_dict: The dictionary to be flattened.

    Returns:
        A flattened dictionary with no nested dictionaries.
    """
    flattened: Dict[str, Any] = {}
    for key, value in nested_dict.items():
        if isinstance(value, dict):
            sub_flattened = flatten_dict(value)
            for subkey, subval in sub_flattened.items():
                flattened[f"{key}.{subkey}"] = subval
        else:
            flattened[key] = value
    return flattened

from typing import List, Union

def quicksort(arr: List[Union[int, float]]) -> List[Union[int, float]]:
    """Sorts a list of numbers using the quicksort algorithm.

    Args:
        arr: A list of integers or floats to be sorted.

    Returns:
        A new sorted list containing all elements from arr.

    Raises:
        TypeError: If arr is not a list or if any element is not a number.
    """
    if not isinstance(arr, list):
        raise TypeError("Input must be a list")
    for num in arr:
        if not isinstance(num, (int, float)):
            raise TypeError("All elements must be numbers")

    if len(arr) <= 1:
        return arr.copy()

    pivot = arr[len(arr) // 2]

    less_than = [x for x in arr if x < pivot]
    equal_to = [x for x in arr if x == pivot]
    greater_than = [x for x in arr if x > pivot]

    return quicksort(less_than) + equal_to + quicksort(greater_than)

import math

def is_prime(n: int) -> bool:
    """
    Checks whether a given integer is a prime number.

    Args:
        n: The number to check for primality.

    Returns:
        True if n is prime, False otherwise.
    """
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    max_divisor = math.isqrt(n)
    for i in range(3, max_divisor + 1, 2):
        if n % i == 0:
            return False
    return True

def count_primes(numbers):
    # Initialize count of primes to 0
    count = 0
    for num in numbers:
        # Numbers less than 2 are not primes
        if num < 2:
            continue
        is_prime = True
        # Check divisors up to the square root of num
        for i in range(2, int(num ** 0.5) + 1):
            if num % i == 0:
                is_prime = False
                break
        if is_prime:
            count += 1
    return count

def is_valid(s: str) -> bool:
    has_lowercase = False
    allowed_punctuation = {',', '.', '!', '?'}
    for char in s:
        if not (char.islower() or char in allowed_punctuation):
            return False
        if char.islower():
            has_lowercase = True
    return has_lowercase

def generate_strings(n):
    # Base case: return empty list if n is 0
    if n == 0:
        return []
    # Start with all single-character strings for n=1
    elif n == 1:
        return [chr(c) for c in range(ord('a'), ord('z')+1)]

    result = []
    # Recursively build strings of length n-1
    for s in generate_strings(n-1):
        last_char = s[-1]
        # Try appending each lowercase letter except the last character
        for c in 'abcdefghijklmnopqrstuvwxyz':
            if c != last_char:
                result.append(s + c)
    return result

